using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with the default reflection-based resolver
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed retrieval — returns JsonTypeInfo<T> directly
JsonTypeInfo<Person> typedInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person>() returned: {typedInfo.Type.Name}");

// Round-trip to prove it works
var json = JsonSerializer.Serialize(new Person("Alice", 30), typedInfo);
Console.WriteLine($"Serialized: {json}");

Person? p = JsonSerializer.Deserialize(json, typedInfo);
Console.WriteLine($"Deserialized: {p}");

// 2) Probe without throwing — TryGetTypeInfo returns false if unavailable
//    Use an empty resolver so nothing is resolvable.
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver
    {
        Modifiers = { static ti => { if (ti.Type == typeof(Order)) ti = null!; } }
    }
};

// Person IS resolvable
if (limited.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info))
    Console.WriteLine($"\nTryGetTypeInfo(Person) succeeded: {info!.Type.Name}");
else
    Console.WriteLine("\nTryGetTypeInfo(Person) returned false");

// Use a resolver that explicitly returns null for Order
var empty = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine() // resolves nothing
};

if (empty.TryGetTypeInfo(typeof(Order), out _))
    Console.WriteLine("TryGetTypeInfo(Order) succeeded");
else
    Console.WriteLine("TryGetTypeInfo(Order) returned false — no exception thrown!");

public record Person(string Name, int Age);
public record Order(int Id, decimal Total);

